        woodSegment(oak, "Oak limb", origin, elbow, girth * .46, bark, false)
        woodSegment(oak, "Branch tip", elbow, tip, girth * .27, bark, false)
        if branch <= 3 then
            woodSegment(oak, "Exposed root", position + vector(0, .5, 0),
